// Builds content/src/kana/strokes.ts (the Ink Storm stroke references) from KanjiVG.
//
//   npx tsx tools/content-strokes.ts [folder-of-svgs]
//
// With a folder, reads <codepoint>.svg files from it (e.g. 03042.svg); without one, fetches
// each file from github.com/KanjiVG/kanjivg with curl. Each stroke's SVG path (cubic Béziers)
// is flattened, scaled from KanjiVG's 109-unit box to 0–1 and simplified to a few points
// (Ramer–Douglas–Peucker), start → end. KanjiVG is © Ulrich Apel, CC BY-SA 3.0; the
// generated file carries the attribution.

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { kana } from '../content/src/kana/kana.js';
import { BOX, flatten, round, simplify, strokePaths, svgFor, TOLERANCE, type Pt } from './kanjivg.js';

const dir = process.argv[2];
const lines: string[] = [];
for (const k of kana.filter((x) => x.kind === 'basic')) {
  const paths = strokePaths(svgFor(k.char, dir));
  if (!paths.length) throw new Error(`No strokes for ${k.char}`);
  const strokes = paths.map((d) => simplify(flatten(d).map(([x, y]): Pt => [x / BOX, y / BOX]), TOLERANCE).map(([x, y]) => `[${round(x)}, ${round(y)}]`));
  lines.push(`  { kanaId: '${k.id}', char: '${k.char}', strokes: [${strokes.map((s) => `[${s.join(', ')}]`).join(', ')}] },`);
}

const out = `// GENERATED by tools/content-strokes.ts from KanjiVG. Do not edit by hand; re-run the tool.
//
// Stroke references for the Ink Storm wave (Kana Yōkai Raid): every basic hiragana and
// katakana, strokes in standard order, each a simplified polyline from start to end in a
// 0–1 box (x right, y down).
//
// Derived from KanjiVG (https://kanjivg.tagaini.net), © Ulrich Apel and contributors,
// licensed under Creative Commons Attribution-Share Alike 3.0
// (https://creativecommons.org/licenses/by-sa/3.0/). This derived data is shared under the
// same licence.

import type { KanaStrokes } from '../types.js';

export const kanaStrokes: KanaStrokes[] = [
${lines.join('\n')}
];
`;
writeFileSync(fileURLToPath(new URL('../content/src/kana/strokes.ts', import.meta.url)), out);
console.log(`wrote ${lines.length} kana`);
